mapper.sql:
WHERE

total.TG_BUSI_TYPE = #{TG_BUSI_TYPE_ZZG}
and total.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_ZQ}

and PP.INVEST_YESORNO = #{YES_NO_YES}
and IFNULL(total.IS_CANCEL,#{YES_NO_NO}) = #{YES_NO_NO}


        #{item}




        #{item}



    and (pp.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName})
    OR pp.PARENT_PORTFOLIO_ID IN (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName}))



        #{item}



    and total.TRADE_DATE >= STR_TO_DATE(#{tradeDateStart},'%Y-%M-%d ')


    and total.TRADE_DATE <= STR_TO_DATE(#{tradeDateEnd},'%Y-%M-%d ')


    and total.TRADE_MARKET =#{tradeMarket}


    and totalAdd.ENTRUST_ID =#{entrustId}

mapper.select:
SELECT
sum(IFNULL(psp.amount,0))*100 amount
FROM
PTL_SEC_POSITION psp
where HODING_TYPE = #{hodingType}
and psp.PORTFOLIO_ID = #{portfolioId}
and psp.FINPROD_ID = #{finprodId}
and psp.CDATE <= STR_TO_DATE(#{cdate},'%Y-%M-%d ')

    and psp.BRANCH = #{branch}


    and psp.INV_AIM = #{invAim}


    and psp.ccy = #{ccy}


    and psp.SEC_ACCT_ID = #{secAcctId}


    and psp.SEC_ACCT_ID = #{chlId}

and not exists (
select
1
from
PTL_SEC_POSITION tpsp
where
tpsp.CDATE <= STR_TO_DATE(#{cdate},'%Y-%M-%d ')
and tpsp.HODING_TYPE = psp.HODING_TYPE
and tpsp.PORTFOLIO_ID = psp.PORTFOLIO_ID
and tpsp.FINPROD_ID = psp.FINPROD_ID
and tpsp.BRANCH = psp.BRANCH
and tpsp.INV_AIM = psp.INV_AIM
and tpsp.CCY = psp.CCY
and tpsp.SEC_ACCT_ID = psp.SEC_ACCT_ID
and tpsp.CDATE > psp.CDATE
)
